object Ar : Tr() {
    override fun pluralCategory(count: Int): PluralCategory = when {
        count == 0 -> PluralCategory.ZERO
        count == 1 -> PluralCategory.ONE
        count == 2 -> PluralCategory.TWO
        count % 100 in 3..10 -> PluralCategory.FEW
        count % 100 in 11..99 -> PluralCategory.MANY
        else -> PluralCategory.OTHER
    }
