object Ru : Tr() {
    override fun pluralCategory(count: Int): PluralCategory {
        val n = kotlin.math.abs(count)
        val mod10 = n % 10
        val mod100 = n % 100
        return when {
            mod10 == 1 && mod100 != 11 -> PluralCategory.ONE
            mod10 in 2..4 && mod100 !in 12..14 -> PluralCategory.FEW
            else -> PluralCategory.MANY
        }
    }
